"""Readable evidence hierarchy for Gate; no new model evaluation."""
import json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'results/gate_attribution_check'
def main():
 s=json.loads((R/'summary.json').read_text());a=json.loads((R/'independent_audit.json').read_text());assert a['status']=='PASS_INDEPENDENT_LOCAL_SCALAR_CONTROLS'
 conditions=['test_id','test_long_gap','test_distractor_shift'];names=['Ordinary','Long gap','Distractors'];old=[s['by_condition'][c]['feature_checks']['actual_feature_pass'] for c in conditions];control=[s['by_condition'][c]['feature_checks']['controlled_feature_pass'] for c in conditions]
 plt.rcParams.update({'font.size':11,'axes.spines.top':False,'axes.spines.right':False})
 fig,axes=plt.subplots(1,2,figsize=(11.2,4.3),gridspec_kw={'width_ratios':[1.15,1]});x=np.arange(3)
 ax=axes[0];ax.axhline(0,color='.5',linewidth=.8)
 for offset,k,marker,lab in [(-.1,'actual_delta','o','Actual predictor'),(.1,'mean_control_delta','s','Offline mean-replacement control')]:
  data=[s['by_condition'][c][k] for c in conditions];v=np.array([d['mean'] for d in data]);lo=np.array([d['low'] for d in data]);hi=np.array([d['high'] for d in data]);ax.errorbar(x+offset,v,yerr=[v-lo,hi-v],color='black',fmt=marker,markerfacecolor='black' if offset<0 else 'white',capsize=3,label=lab)
 ax.set(xticks=x,xticklabels=names,ylabel='Future-feature error difference',title='A. Effect of deleting the cue');ax.legend(frameon=False,fontsize=8,loc='center right')
 ax=axes[1];ax.bar(x-.18,old,.34,color='.25',label='Actual feature checks');ax.bar(x+.18,control,.34,color='white',hatch='///',edgecolor='black',label='Offline diagnostic control')
 for xx,v in zip(x-.18,old):ax.text(xx,v+.35,f'{v}/18',ha='center',fontsize=9)
 for xx,v in zip(x+.18,control):ax.text(xx,v+.35,f'{v}/18',ha='center',fontsize=9)
 ax.set(xticks=x,xticklabels=names,ylim=(0,20),ylabel='Feature checks meeting criteria (out of 18)',title='B. Shared-part control');ax.legend(frameon=False,fontsize=8,loc='upper right')
 fig.text(.02,.015,'Positive in A means deleting the cue hurts. Error bars: paired 95% intervals over 128 base pairs per condition.\nThe offline control uses sibling-pair predictions; it is not an online model, a repaired predictor, or a new Phase 1 pass.',fontsize=9)
 fig.tight_layout(rect=(0,.10,1,1));f=R/'figures';f.mkdir(exist_ok=True);fig.savefig(f/'predictor_vs_cost.png',dpi=180,bbox_inches='tight');fig.savefig(f/'predictor_vs_cost.pdf',bbox_inches='tight');plt.close(fig)
 table='\n'.join(f'| {n} | {o}/18 | {c}/18 |' for n,o,c in zip(names,old,control))
 report=f'''# Gate: predictor failure or deletion-cost failure?\n\n18 October 2026. Minimal local analysis of already verified results. **Zero model calls, zero training and zero additional GPU seconds.** No threshold, seed, sample or horizon changed.\n\n## Decision first\n\n**The strongest evidence is for predictor errors, plus a limitation in interpreting full-feature deletion cost as task importance. It is not a clean either/or.** We verified that the implemented score measures the registered future-feature error difference; we did not find a score-computation bug. But that score describes this predictor's behavior under its loss, not an intrinsic value attached to a historical frame.\n\nThe present Gate predictor remains unsuitable as a generally reliable source of task-importance labels. Its original both-error result stays **10/54**, or **1/18** after averaging seeds within each pair. Nothing in the diagnostic below is a new model pass.\n\n## 1. What is the score actually measuring?\n\nEach candidate deletes one frame from a common three-frame parent and retains exactly two past frames plus the same four recent frames. The current assay measures full-feature squared error against the actual future. It compares deleting the cue with the average of the two other deletions. All alternatives have the same capacity.\n\nIt does **not** simply measure how much a prediction changes. A large change can improve a wrong prediction. Algebraically:\n\n`change in target loss = squared prediction change + interaction with the original prediction error`\n\nA tested example moves a scalar prediction from1 to3: the squared change is4 whether the target is1 or3, but the true loss change is+4 or−4. Our actual assay uses target loss, so this particular proxy error is not its implementation failure. Future target access is legitimate for offline evaluation, but this assay is not a ready-made online scorer.\n\n## 2. The smallest additional control\n\nWe reused the existing **41,472 Gate outcomes**, represented by **6,912 paired rows**. These repeat128 base pairs per condition across three seeds, cue positions and horizons; they are not 6,912 independent scenes. All input files were checked against the previous native-before/local/native-after transfer hashes.\n\nA paired prediction consists of:\n\n- A shared part: the average of the two sibling predictions.\n- A difference: how the two predicted futures differ.\n\nSquared error splits exactly into shared-part error plus difference error. We replaced the shared part of each cue-retaining pair with the shared part predicted when the cue was deleted, while preserving the retained-cue predicted difference. This is a controlled prediction-level intervention calculable from saved scalar error components. It requires sibling-pair predictions and therefore **cannot be deployed on a single trajectory**. We did not infer the classification outcome after this intervention.\n\nThe question is narrow: if the shared distortion were removed, how much of the feature-score failure would remain?\n\n## 3. Results: shared distortion matters, but is not the whole problem\n\n| Condition | Actual predictor: feature checks | Offline shared-part control: feature checks |\n|---|---:|---:|\n{table}\n| All conditions | **11/54** | **34/54** |\n\nThese use the same10% relative feature effect and strictly positive paired95% bootstrap lower bound, over128 base pairs. They are **feature-only diagnostic counts**; the intervention's task-error outcomes were not calculated. The actual joint 10/54 result has not changed.\n\n![Minimal predictor-versus-cost check](../results/gate_attribution_check/figures/predictor_vs_cost.png)\n\n**Read the figure:** In A, a positive number means deleting the cue causes more feature error, which is the intended direction. Black circles are the real predictor; open squares are the offline control. In B, hatched bars describe the diagnostic intervention, not an improved deployable model.\n\nOf the40 actual cells whose mean feature effect points the wrong way, **30/40 reverse to the intended direction** after shared-part replacement. Only21 of those40 also meet the original feature effect-size and confidence conditions.\n\nLong gap is the decisive remaining failure. Its actual mean effect is−0.12307, with95% interval[−0.13422,−0.11179]. After shared-part replacement the effect is still **−0.00789**, interval **[−0.01418,−0.00175]**. Even after this favorable shared-part intervention, the predicted difference between futures is wrong enough to make cue retention worse on average. A common-offset correction alone cannot solve that failure.\n\n## 4. Why this does not exonerate the metric\n\nIn38 of the40 wrong-feature-direction cells, keeping the cue improves mean binary task error. Full-feature MSE and binary correctness are therefore not interchangeable objectives.\n\nHowever, only **4/40** improve squared error along the existing class-readout direction. Thus the mismatch cannot simply be dismissed as irrelevant background dimensions. Binary correctness only checks which side of a decision boundary a prediction falls on; a correct but badly scaled continuous prediction can still have large squared error. Orthogonal to one readout also does not mean universally task-irrelevant.\n\nThe companion frame matters too: existing raw results show a feature-effect sign flip between cue-retaining companion choices in **2,918/6,912** repeated records. Among records with a task-improving choice, **3,647/3,839** have at least one joint feature-and-task improving choice. These are descriptive, future-informed existence results, not attainable policy accuracies. The metric is model-, objective- and retained-set-dependent; assigning one context-free importance label to a cue is not justified.\n\n## 5. Sanity controls and their limits\n\nThe fixed decoder reads **1,536/1,536 real target features** correctly; this is feature decoding, not forecasting accuracy. When the cue is deleted, paired future predictions are identical in all6,912 rows. Hence cue deletion really removes a distinction available in the target features.\n\nAn analytical ideal-cue predictor that returns the actual future when the cue is retained and the true pair mean when it is absent gives the intended positive feature deletion effect. Conversely, identical predictions across every deletion give exactly zero deletion effect. These are algebraic positive/negative controls using future truth, **not additional trained models or empirical successes**. They do not show that every target coordinate is predictable from legal inputs. They show the loss is capable of registering the intended distinction, while not establishing it as a universally correct task-importance metric.\n\nAn independent local process reconstructed216 actual/control/ideal feature-statistic cells from primitive scalar components and reproduced all decisions. Four local fixtures separately tested the pair-mean identity, true-loss versus prediction-drift distinction, ideal/no-response controls, and a long-gap-style wrong-contrast counterexample. These checks validate the analysis, not the scientific hypothesis.\n\n## 6. What to fix next, without another blind training run\n\nThe justified repair targets are **shared prediction distortion** and **long-gap future-contrast distortion**. A smaller global history coefficient is already ruled out as a validation-selected repair in the tested grid: original validation selected alpha1, so that candidate was unchanged. The present oracle-assisted centering is a localization tool, not a legal replacement predictor.\n\nThe next discriminating model check, if further work is pursued, should be a **frozen-model validation assay with the same two-frame deletion pools**, using existing validation episodes/caches. Check common and contrast errors before considering any calibration or update. This would distinguish ordinary validation success from failure on the actual deletion inputs without using test outcomes to choose a fix. It has not been executed in this local-only step. If a correction cannot be defined and selected from legal single-trajectory inputs on validation, stop the current Gate configuration rather than train a retention policy to imitate its inconsistent labels.\n\nDo not replace full-feature MSE with classification error, delete failing conditions, expand a test-tuned calibration search, or claim all Gate failures are due to a harmless offset. Original Proposal Phase1_GO and joint Gate-and-Motion policy readiness remain false; fresh9137 stays closed. Motion deletion evidence remains a separate scoped result, not a waiver of Gate.\n\n## Evidence and related methodology\n\n[ROAR, Hooker et al., NeurIPS2019](https://papers.neurips.cc/paper/9167-a-benchmark-for-interpretability-methods-in-deep-neural-networks.pdf) cautions that deletion-induced changes can conflate a model's behavior on modified inputs with information importance. We borrow that distinction, not its expensive retraining procedure. Equal-capacity forks control memory count but do not prove absence of input-distribution shift. Here distribution shift is a hypothesis; no new check uniquely identifies its origin.\n\n[Protocol](../experiments/gate_attribution_check/PROTOCOL.md), [machine-readable results](../results/gate_attribution_check/summary.json), [independent audit](../results/gate_attribution_check/independent_audit.json), and [per-pair control values](../results/gate_attribution_check/pair_controls.csv). No HPC allocation was opened, no GPU budget was consumed and GitHub was not updated.\n'''
 for old,new in [('from1 to3','from 1 to 3'),('change is4','change is 4'),('target is1 or3','target is 1 or 3'),('is+4 or−4','is +4 or −4'),('repeat128','repeat 128'),('not 6,912','not 6,912'),('same10%','same 10%'),('paired95%','paired 95%'),('over128','over 128'),('the40','the 40'),('Only21','Only 21'),('those40','those 40'),('is−0.12307','is −0.12307'),('with95%','with 95%'),('interval[','interval ['),('In38','In 38'),('all6,912','all 6,912'),('reconstructed216','reconstructed 216'),('alpha1','alpha = 1'),('fresh9137','fresh 9137'),('NeurIPS2019','NeurIPS 2019')]:report=report.replace(old,new)
 (ROOT/'docs/GATE_PREDICTOR_VS_COST.md').write_text(report)
 print(json.dumps(dict(report='docs/GATE_PREDICTOR_VS_COST.md',actual_feature=11,offline_control_feature=34,actual_joint=10,GPU_added=0)))
if __name__=='__main__':main()
